/**
 * 3D and Materials: Effect > 3D and Materials > Extrude, Revolve, Inflate
 * and Rotate as live, non-destructive effects on paths, compound paths,
 * groups and type, and the 3D and Materials panel that edits them.
 *
 * The effect is a record in node.effects (type 'threeD', see params.js),
 * so the Appearance panel lists it (clicking it opens the panel), graphic
 * styles carry it and Apply Last Effect repeats it. The artwork is
 * generated by the live framework (live-kind.js): meshes from the
 * outlines (mesh.js), hidden-surface ordering and shading (scene.js,
 * shading.js), output as flat vector faces. The solids also export as
 * OBJ and glTF files (export-3d.js, export-ui.js).
 */
import './styles.css';
import './live-kind.js';
import { registerEffectType, EFFECTS, normalizeEffect } from '../paint/effects-model.js';
import { effectTargets, rememberEffect } from '../paint/effects-ui.js';
import { registerThreeDIcons } from './icons.js';
import { ThreeDPanel } from './panel.js';
import { installThreeDExport } from './export-ui.js';
import { EFFECT_TYPE, DEFAULTS, RANGES, ENUMS, KINDS, KIND_DEFAULTS, normalizeRecord, describe, newParams, threeDRecord } from './params.js';

const SHAPES = new Set(['path', 'compound', 'group', 'text']);

registerEffectType(EFFECT_TYPE, {
  label: '3D and Materials',
  command: 'effect.3d.extrude',
  defaults: { ...DEFAULTS },
  ranges: RANGES,
  enums: ENUMS,
  normalize: normalizeRecord,
  describe,
});

const LOOK_KEYS = new Set(['rotX', 'rotY', 'rotZ', 'perspective', 'material']);

/** A kind's own shape settings (not its starting orientation or material). */
function shapeDefaults(kind) {
  return Object.fromEntries(Object.entries(KIND_DEFAULTS[kind] || {}).filter(([k]) => !LOOK_KEYS.has(k)));
}

/** Selected objects a 3D effect can apply to. */
function shapeTargets(app) {
  return app.editor ? effectTargets(app.editor).filter((n) => SHAPES.has(n.type)) : [];
}

/** Open the panel on a tab. */
export function openThreeDPanel(app, tab = 'object') {
  app.openPanel('3d');
  const p = app.dock?.panels.get('3d');
  p?.showTab?.(tab);
  return p;
}

/**
 * Give the selection a 3D effect of a kind: objects that already have one
 * switch to the kind (keeping their other settings), the rest get a new
 * effect (from `params`, else the kind's defaults). Opens the panel.
 */
export function applyThreeD(app, kind, { params = null, open = true } = {}) {
  const ed = app.editor;
  const targets = shapeTargets(app);
  if (!ed || !targets.length) {
    app.notify('Select artwork to apply a 3D effect to.');
    return false;
  }
  const label = `3D ${KINDS.find((k) => k.id === kind)?.label || ''}`.trim();
  let last = null;
  ed.doc.transact(label, () => {
    for (const n of targets) {
      const rec = threeDRecord(n);
      const list = (n.effects || []).slice();
      if (rec) {
        // Switching type keeps the look (orientation, material, light) and takes the new type's shape settings.
        const switched = rec.fx.kind === kind ? rec.fx : { ...rec.fx, ...shapeDefaults(kind), kind };
        list[rec.index] = normalizeEffect({ ...switched, ...(params || {}), kind, hidden: false });
      } else list.push(normalizeEffect({ ...newParams(kind), ...(params || {}), type: EFFECT_TYPE, kind }));
      ed.doc.update(n.id, { effects: list });
      last = threeDRecord(ed.doc.get(n.id))?.fx;
    }
  });
  if (last) rememberEffect(app, last);
  if (open) openThreeDPanel(app, 'object');
  return true;
}

export function install(app) {
  registerThreeDIcons();
  app.registerPanel(ThreeDPanel);
  installThreeDExport(app);
  const hasShapes = (a) => shapeTargets(a).length > 0;
  app.commands.register(
    KINDS.map((k) => ({
      id: `effect.3d.${k.id}`,
      label: `${k.label}...`,
      enabled: hasShapes,
      run: (a) => applyThreeD(a, k.id),
    })),
  );
  // The Appearance panel, Last Effect and graphic styles reach the effect through its record.
  EFFECTS[EFFECT_TYPE].openDialog = (a, { params, edit } = {}) => {
    if (edit) {
      const n = a.editor?.doc.get(edit.id);
      if (n && a.editor && !a.editor.selection.has(n.id)) a.editor.select([n.id]);
      openThreeDPanel(a, 'object');
      return true;
    }
    return applyThreeD(a, params?.kind || 'extrude', { params });
  };
}
